const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

async function run(action) {
  const response = await fetch(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action, mode: 'sync', args: [] }),
  });
  const raw = await response.text();
  if (!response.ok) {
    throw new Error(`${action} failed: ${response.status} ${raw}`);
  }
  return raw ? JSON.parse(raw) : null;
}

const syncResult = await run('plane_sync_backlog');
const dedupeResult = await run('plane_dedupe_backlog');

const dateStamp = new Date().toISOString().slice(0, 10);
const reportRelativePath = `maintenance/${dateStamp}.md`;
const reportContent = [
  '# Project Automation Maintenance',
  '',
  `Generated: ${new Date().toISOString()}`,
  '',
  '## plane_sync_backlog',
  '',
  '```json',
  JSON.stringify(syncResult, null, 2),
  '```',
  '',
  '## plane_dedupe_backlog',
  '',
  '```json',
  JSON.stringify(dedupeResult, null, 2),
  '```',
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) {
  const body = await writeResponse.text();
  throw new Error(`Runner report write failed: ${writeResponse.status} ${body}`);
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    syncResult,
    dedupeResult,
    reportRelativePath,
  },
}];
